INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r0','振铎','cao-chunqiu','[]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','周武王之弟，传统称名振铎。周灭商后受封于曹，封地在今山东定陶一带，为曹国始封君；早期事迹与具体在位起讫记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叔振铎"}]',NULL,NULL,'叔振铎','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-r1','脾','cao-chunqiu','["曹太伯"]','姬','曹',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','曹国第二代君主，太伯。西周时期在位，史料记述较少，事迹不详，维持小国局面，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹太伯"}]','太',NULL,'太伯','[]');
